if (!SERVICE_KEY) {
  console.error("❌ Falta SUPABASE_SERVICE_KEY en esta terminal.");
  process.exit(1);
}

const supabase = createClient(SUPABASE_URL, SERVICE_KEY, {
  auth: { persistSession: false, autoRefreshToken: false }
});

function contentType(file) {
  const ext = path.extname(file).toLowerCase();
  if (ext === ".mp4") return "video/mp4";
  if (ext === ".png") return "image/png";
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  return "application/octet-stream";
}

async function uploadSet(files, localDir, remoteDir) {
  let ok = 0, skipped = 0, failed = 0;
  for (let i = 0; i < files.length; i++) {
    const name = files[i];
    const local = path.join(localDir, name);
    const remote = `${remoteDir}/${name}`;

    if (!fs.existsSync(local)) {
      console.log(`❌ NO ENCONTRADO ${name}`);
      failed++;
      continue;
    }

    const data = fs.readFileSync(local);
    const { error } = await supabase.storage.from(BUCKET).upload(remote, data, {
      contentType: contentType(name),
      upsert: false,
      cacheControl: "31536000"
    });

    if (error) {
      if (/already exists|duplicate/i.test(error.message || "")) {
        skipped++;
        console.log(`↪️ ${i+1}/${files.length} ya existe: ${remote}`);
      } else {
        failed++;
        console.log(`❌ ${i+1}/${files.length} ${remote} -> ${error.message}`);
      }
    } else {
      ok++;
      console.log(`✅ ${i+1}/${files.length} ${remote}`);
    }
  }
  return { ok, skipped, failed };
}

(async () => {
  console.log(`🚀 VitorFit Fit3D: ${videos.length} vídeos + ${images.length} imágenes`);
  console.log("📁", ROOT);

  if (!fs.existsSync(VIDEO_DIR) || !fs.existsSync(IMAGE_DIR)) {
    console.error("❌ No encuentro uploads\\videos o uploads\\images dentro de bulk-download.");
    process.exit(1);
  }

  console.log("\n🎬 SUBIENDO VÍDEOS...");
  const vr = await uploadSet(videos, VIDEO_DIR, "videos");

  console.log("\n🖼️ SUBIENDO IMÁGENES...");
  const ir = await uploadSet(images, IMAGE_DIR, "images");

  console.log("\n🏁 TERMINADO");
  console.log("Vídeos:", vr);
  console.log("Imágenes:", ir);

  if (vr.failed || ir.failed) process.exitCode = 2;
})().catch(err => {
  console.error("❌ Error general:", err);
  process.exit(1);
});
